mapper.select:
select id, member_id as memberId, name, phone, address, longitude, latitude, category, tags, source,
       contact_open as contactOpen, coop_open as coopOpen, status, del_flag as delFlag,
       create_time as createTime, update_time as updateTime
from merchant_lead

    del_flag = 0
     and name like concat('%', #{name}, '%')
     and phone like concat('%', #{phone}, '%')
     and category = #{category}
     and source = #{source}
     and status = #{status}
     and member_id = #{memberId}

order by id desc

mapper.update:
update merchant_lead
member_id = #{memberId}, name = #{name}, phone = #{phone}, address = #{address}, longitude = #{longitude}, latitude = #{latitude}, category = #{category}, tags = #{tags}, source = #{source}, contact_open = #{contactOpen}, coop_open = #{coopOpen}, status = #{status}, update_time = #{updateTime}
where id = #{id}
